import React, { useState, useEffect } from "react";
import { collection, onSnapshot, query, where } from "firebase/firestore";
import { db } from "../../firebase/config"; // Import the database connection
import PetCard from "../../components/PetCard";
import "./AdopterDashboard.css";

const AdopterDashboard = () => {
    const [pets, setPets] = useState([]); // Store the real pets here
    const [loading, setLoading] = useState(true);

    // States for filtering
    const [search, setSearch] = useState("");
    const [filters, setFilters] = useState({
        type: "",
        age: "",
    });

    // 1. READING DATA FROM FIREBASE
    useEffect(() => {
        // Create a reference to the "pets" collection
        // We use `where("adopted", "==", false)` to show only available pets
        const q = query(collection(db, "pets"), where("adopted", "==", false));

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const petsData = snapshot.docs.map((doc) => ({
                id: doc.id,
                ...doc.data(),
            }));
            setPets(petsData);
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const filteredPets = pets.filter((pet) => {
        const term = search.toLowerCase();

        const matchSearch =
            pet.name.toLowerCase().includes(term) ||
            pet.breed.toLowerCase().includes(term) ||
            (pet.type && pet.type.toLowerCase().includes(term));
        const matchType = filters.type
            ? pet.type && pet.type.toLowerCase() === filters.type.toLowerCase()
            : true;

        const matchAge = true;
        return matchSearch && matchType && matchAge;
    });

    return (
        <div className="adopter-container">
            <header className="dashboard-header">
                <div className="header-left">
                    <h1 className="title">🐾 Find Your Perfect Friend</h1>
                    <p className="subtitle">
                        Explore pets available for adoption from all shelters.
                    </p>
                </div>
                {/* You can add profile/logout buttons here if needed */}
            </header>

            {/* SEARCH BAR */}
            <div className="search-section">
                <input
                    type="text"
                    className="search-input"
                    placeholder="Search by name, breed..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>

            {/* FILTERS */}
            <div className="filters-container">
                <select
                    className="filter-select"
                    value={filters.type}
                    onChange={(e) =>
                        setFilters({ ...filters, type: e.target.value })
                    }
                >
                    <option value="">All Types</option>
                    <option value="Dog">Dogs</option>
                    <option value="Cat">Cats</option>
                    <option value="Hamster">Hamsters</option>
                    <option value="Rabbit">Rabbits</option>
                    <option value="Parrot">Parrots</option>
                </select>

                <select
                    className="filter-select"
                    value={filters.age}
                    onChange={(e) =>
                        setFilters({ ...filters, age: e.target.value })
                    }
                >
                    <option value="">Any Age</option>
                    <option value="puppy">Puppy</option>
                    <option value="adult">Adult</option>
                    <option value="senior">Senior</option>
                </select>
            </div>

            {/* PET LIST */}
            <h2 className="section-title">
                Available Pets ({filteredPets.length}) 🐶🐱
            </h2>

            {loading ? (
                <p>Loading pets...</p>
            ) : filteredPets.length === 0 ? (
                <p>No pets matched your criteria. :(</p>
            ) : (
                <div className="cards-container">
                    {filteredPets.map((pet) => (
                        <PetCard key={pet.id} pet={pet} />
                    ))}
                </div>
            )}
        </div>
    );
};

export default AdopterDashboard;
